  $('frame-counter').textContent=`${state.view.indexOf(state.index)+1} / ${state.view.length}`;$('scale-label').textContent=`${state.field.fov} × ${state.field.fov} arcmin`;$('timeline').value=state.view.indexOf(state.index);
