// Outage handling: when the IRSA search is down, offer the saved example and retry on a backoff.
const outage={timer:null,tick:null,attempt:0},RETRY_DELAYS=[20,40,80,160,300];
function clearOutage(){clearTimeout(outage.timer);clearInterval(outage.tick);$('outage-actions').hidden=true;}
function scheduleRetry(revision){if(outage.attempt>=RETRY_DELAYS.length){$('retry-countdown').textContent='Automatic retries paused. Use Retry now when you are ready.';return;}let left=RETRY_DELAYS[outage.attempt++];const show=()=>{$('retry-countdown').textContent=`Retrying automatically in ${left}s · attempt ${outage.attempt} of ${RETRY_DELAYS.length}`;};show();outage.tick=setInterval(()=>{if(--left>0)show();},1000);outage.timer=setTimeout(()=>{clearInterval(outage.tick);if(revision===state.revision)search({auto:true});},left*1000);}
