async function dateRange(){if(!state.catalog)return;const start=$('start-date').value,end=$('end-date').value;if(start&&end&&start>end){message('The start date must be on or before the end date.',true);return;}const records=state.catalog.records.filter(r=>(!start||r.date.slice(0,10)>=start)&&(!end||r.date.slice(0,10)<=end));if(!records.length){message('No observations fall in that date range.',true);return;}stop();state.controller?.abort();state.controller=new AbortController();const revision=++state.revision;setBusy(true);status('Loading selected dates…',true);await loadFrames(records,revision,state.controller.signal);}
