$('save-report').addEventListener('click',()=>{const report={project:'Asterlight — SPHEREx through time',version:3,exportedAt:new Date().toISOString(),field:state.field,catalog:{retrievedAt:state.catalog?.retrievedAt,total:state.catalog?.total,sources:state.catalog?.source,warnings:state.catalog?.warnings},display:{mode:state.mode,maskSuspectPixels:$('mask').checked,sharedBrightnessScale:$('stretch').checked,reference:state.frames[state.reference]?.record.id,current:state.frames[state.index]?.record.id,similarWavelengthOnly:$('matched').checked},marker:state.marker,notes:$('notes').value,frames:state.frames.map(({pixels,mask,...f})=>f),failedFrames:state.failed,method:'ICRS TAN grid, TAN-SIP inverse mapping, bilinear resampling. Difference: median-background-subtracted B−A with overlapping center bandpasses. No PSF matching, calibrated variability inference, automated detection, or discovery claim.'};save('asterlight-observation-log.json',JSON.stringify(report,null,2),'application/json');});
